#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_2.md ]] || { echo 'Run from your repository root after the second Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_THREE'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/watch_days.dart': '',
'desktop/hyper_player/lib/screens/statistics_screen.dart': '',
'desktop/hyper_player/lib/screens/info_sheets.dart': '',
'desktop/hyper_player/test/statistics_sheets_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_3.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Statistics, Manual, About and Privacy update applied. Android unchanged.')
VISUAL_GROUP_THREE
